  1094  int usbredirparser_do_write(struct usbredirparser *parser_pub)
  1095  {
  1096      struct usbredirparser_priv *parser =
  1097          (struct usbredirparser_priv *)parser_pub;
  1098      struct usbredirparser_buf* wbuf;
  1099      int w, ret = 0;
  1100
  1101      LOCK(parser);
  1102      for (;;) {
  1103          wbuf = parser->write_buf;
  1104          if (!wbuf)
  1105              break;
  1106
  1107          w = wbuf->len - wbuf->pos;
  1108          w = parser->callb.write_func(parser->callb.priv,
  1109                                       wbuf->buf + wbuf->pos, w);
  1110          if (w <= 0) {
  1111              ret = w;
  1112              break;
  1113          }
  1114
  1115          /* See usbredirparser_write documentation */
  1116          if ((parser->flags & usbredirparser_fl_write_cb_owns_buffer) &&
  1117                  w != wbuf->len)
  1118              abort();
  1119
  1120          wbuf->pos += w;
  1121          if (wbuf->pos == wbuf->len) {
  1122              parser->write_buf = wbuf->next;
  1123              if (!(parser->flags & usbredirparser_fl_write_cb_owns_buffer))
  1124                  free(wbuf->buf);
  1125              free(wbuf);
  1126              parser->write_buf_count--;
  1127          }
  1128      }
  1129      UNLOCK(parser);
  1130      return ret;
  1131  }
