  1147  static void usbredirparser_queue(struct usbredirparser *parser_pub,
  1148      uint32_t type, uint64_t id, void *type_header_in,
  1149      uint8_t *data_in, int data_len)
  1150  {
  1151      struct usbredirparser_priv *parser =
  1152          (struct usbredirparser_priv *)parser_pub;
  1153      uint8_t *buf, *type_header_out, *data_out;
  1154      struct usb_redir_header *header;
  1155      struct usbredirparser_buf *wbuf, *new_wbuf;
  1156      int header_len, type_header_len;
  1157
  1158      header_len = usbredirparser_get_header_len(parser_pub);
  1159      type_header_len = usbredirparser_get_type_header_len(parser_pub, type, 1);
  1160      if (type_header_len < 0) { /* This should never happen */
  1161          ERROR("error packet type unknown with internal call, please report!!");
  1162          return;
  1163      }
  1164
  1165      if (!usbredirparser_verify_type_header(parser_pub, type, type_header_in,
  1166                                             data_in, data_len, 1)) {
  1167          ERROR("error usbredirparser_send_* call invalid params, please report!!");
  1168          return;
  1169      }
  1170
  1171      new_wbuf = calloc(1, sizeof(*new_wbuf));
  1172      buf = malloc(header_len + type_header_len + data_len);
  1173      if (!new_wbuf || !buf) {
  1174          ERROR("Out of memory allocating buffer to send packet, dropping!");
  1175          free(new_wbuf); free(buf);
  1176          return;
  1177      }
  1178
  1179      new_wbuf->buf = buf;
  1180      new_wbuf->len = header_len + type_header_len + data_len;
  1181
  1182      header = (struct usb_redir_header *)buf;
  1183      type_header_out = buf + header_len;
  1184      data_out = type_header_out + type_header_len;
  1185
  1186      header->type   = type;
  1187      header->length = type_header_len + data_len;
  1188      if (usbredirparser_using_32bits_ids(parser_pub))
  1189          ((struct usb_redir_header_32bit_id *)header)->id = id;
  1190      else
  1191          header->id = id;
  1192      memcpy(type_header_out, type_header_in, type_header_len);
  1193      memcpy(data_out, data_in, data_len);
  1194
  1195      LOCK(parser);
  1196      if (!parser->write_buf) {
  1197          parser->write_buf = new_wbuf;
  1198      } else {
  1199          /* limiting the write_buf's stack depth is our users responsibility */
  1200          wbuf = parser->write_buf;
  1201          while (wbuf->next)
  1202              wbuf = wbuf->next;
  1203
  1204          wbuf->next = new_wbuf;
  1205      }
  1206      parser->write_buf_count++;
  1207      UNLOCK(parser);
  1208  }
